<?php if(!defined('TELEDRIVE_INIT')){exit('Direct access not permitted');}class Helpers{public static function jsonResponse(array $data,int $statusCode=200):void{while(ob_get_level()>0){ob_end_clean();}http_response_code($statusCode);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}public static function error(string $message,int $statusCode=400,array $extra=[]):void{self::jsonResponse(array_merge(['success'=>false,'error'=>$message],$extra),$statusCode);}public static function success(array $data=[],string $message='Success'):void{self::jsonResponse(array_merge(['success'=>true,'message'=>$message],$data),200);}public static function generateUUID():string{$data=random_bytes(16);$data[6]=chr((ord($data[6])&0x0f)|0x40);$data[8]=chr((ord($data[8])&0x3f)|0x80);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($data),4));}public static function formatBytes(int $bytes,int $precision=1):string{$units=['B','MB','MB','GB','TB'];if($bytes<=0)return'0 B';if($bytes<1000)return $bytes.' B';if($bytes<1000000)return round($bytes/1000,$precision).' KB';if($bytes<1000000000)return round($bytes/1000000,$precision).' MB';return round($bytes/1000000000,$precision).' GB';}public static function sanitizeFilename(string $filename):string{$filename=str_replace("\0",'',$filename);$filename=basename($filename);$filename=preg_replace('/[^\w\s\d\-_~,;:\[\]\(\)\.]/u','_',$filename);$filename=ltrim($filename,'.');$filename=trim($filename);if($filename===''){$filename='file_'.time();}return substr($filename,0,200);}public static function removeDir(string $dir):void{if(!is_dir($dir)){return;}$files=array_diff(scandir($dir),['.','..']);foreach($files as $file){$path="$dir/$file";is_dir($path)?self::removeDir($path):@unlink($path);}@rmdir($dir);}}